cards:[
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "1 ▶ The box model — and why border-box is the sane default.",
  "a": "content + padding + border (+ margin). box-sizing: border-box puts padding/border inside the declared width — no more “width + 32px” arithmetic. (Part 2, Idea 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "2 ▶ The cascade order — who wins, and when.",
  "a": "Important + origin first, then specificity, then source order. Inline styles beat selectors (except !important). A tie goes to the later rule. (Part 2, Idea 4)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "3 ▶ Specificity in one breath.",
  "a": "IDs > classes/attrs/pseudo-classes > elements. :is()/:where() let you write complex selectors with LOW specificity — keep yours low so later rules can win. (Part 4.1)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "4 ▶ rem vs em — and the only sane spacing rule.",
  "a": "rem = root em (predictable); em compounds at every nesting level. Use rem for the type/space scale, em only when something should size relative to ITSELF. (Part 4.3)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "5 ▶ Flexbox in one axis — which property controls which axis.",
  "a": "justify-content = MAIN axis placement; align-items = CROSS axis. flex-grow/shrink/basis decide how space is split. State the axis first, then the property. (Part 5.2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "6 ▶ Grid vs flex — the actual selector.",
  "a": "Flex: 1-D, content-sized, items decide. Grid: 2-D, container-sized, tracks decide. auto-fit/minmax(240px, 1fr) = fluid responsive without media queries. (Part 5.3)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "7 ▶ Custom properties — what they are and where they fail.",
  "a": "Design tokens: declared on :root, inherited, overridable at any level, composable with calc(). They do NOT work inside media queries — precompute what breakpoints need. (Part 4.2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "8 ▶ The semantic element set that carries the outline.",
  "a": "header, main, nav, section, article, aside, footer, h1→h6, figure, time, address — the landmarks assistive tech and search use. Every div is a box until you give it meaning. (Part 3.1)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "9 ▶ Forms: the four things every field needs.",
  "a": "A label (for/id), a name, a correct type, and HTML validation (required/pattern) — plus aria-describedby for help text. Labels are click targets AND accessibility names. (Part 3.3)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "10 ▶ The colour law that is not taste.",
  "a": "Contrast: 4.5:1 for normal text, 3:1 for large text (WCAG AA). Hue is taste; contrast is law — every audit tool checks it. (Part 7.3)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "11 ▶ The rendering pipeline, named in order.",
  "a": "HTML → DOM tree; CSS → style (cascade + resolved values) → layout (boxes measured) → paint → composite. The interview-grade narration starts here. (Part 10.1)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "12 ▶ Layout thrash — the one-line explanation.",
  "a": "A JS read after a write forces a SYNCHRONOUS relayout. Batch your DOM reads and writes; one forced reflow a frame is fine, a loop is jank. (Part 10.2)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "13 ▶ Stacking contexts — why z-index stops working.",
  "a": "z-index only orders elements INSIDE the same stacking context. transform/filter/opacity/position create new ones — so “z-index: 9999” loses to a transformed ancestor’s context. (Part 10.3)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "14 ▶ The parser-blocks rules.",
  "a": "CSS blocks rendering. Classic scripts block parsing — defer runs after parsing in order, async fires when ready. Images and fonts do not block parsing, only paint. (Part 10.4)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "15 ▶ LCP / INP / CLS — what each measures and its fix.",
  "a": "LCP: largest content → preload + image sizes. INP: interaction latency → keep the main thread free. CLS: layout shift → reserve space (width/height, stable fonts). (Part 11.1)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "16 ▶ The CSS architecture trade-off — as a senior frames it.",
  "a": "Consistency + change-speed vs file size + constraint: utilities (Tailwind), BEM, or composition. The decision is your team’s consistency cost over a year, not tool dogma. (Part 11.2)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "17 ▶ The responsive default that kills breakpoints.",
  "a": "Intrinsic sizing + flex-wrap + grid auto-fit/minmax + clamp() — layout that reflows by itself; media queries fill the residual gaps. Mobile-first makes the constrained case the default. (Part 6)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "18 ▶ When to hand-write CSS and when not to.",
  "a": "Hand-write: bespoke, small, design-heavy surfaces. Framework/utilities: many screens racing to consistency. Either way the semantic layer and tokens survive the choice. (Part 12)"
 }
],
